package io.storyspace.api;
import io.storyspace.accounts.Account;import io.storyspace.api.ApiDtos.*;import io.storyspace.catalog.*;import io.storyspace.library.*;import io.storyspace.service.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;
@RestController @RequestMapping("/api/library")public class LibraryController {private final CurrentAccount current;private final LibraryRepository library;private final TitleRepository titles;private final RecommendationService rec;
 public LibraryController(CurrentAccount c,LibraryRepository l,TitleRepository t,RecommendationService r){current=c;library=l;titles=t;rec=r;}
 private LibraryDto dto(LibraryItem item){return new LibraryDto(rec.dto(item.getTitle()),item.getState(),item.getProgressPercent(),item.getUserRating(),item.getResumePositionSeconds(),item.getDurationSeconds(),item.getLastPlayedAt());}
 @GetMapping public List<LibraryDto> list(){return library.findByAccountId(current.require().getId()).stream().map(this::dto).toList();}
 @PutMapping("/{titleId}")public LibraryDto save(@PathVariable java.util.UUID titleId){Account a=current.require();Title t=titles.findById(titleId).orElseThrow(()->new IllegalArgumentException("Title not found"));LibraryItem i=library.findByAccountIdAndTitleId(a.getId(),t.getId()).orElseGet(()->new LibraryItem(a,t));i.setState("WATCHLIST");return dto(library.save(i));}
 @DeleteMapping("/{titleId}")public void remove(@PathVariable java.util.UUID titleId){library.findByAccountIdAndTitleId(current.require().getId(),titleId).ifPresent(library::delete);}
 @PatchMapping("/{titleId}/progress")public LibraryDto progress(@PathVariable java.util.UUID titleId,@Valid @RequestBody ProgressRequest r){LibraryItem i=library.findByAccountIdAndTitleId(current.require().getId(),titleId).orElseThrow(()->new IllegalArgumentException("Add this title to your library first"));if(r.currentTime()!=null||r.duration()!=null){if(r.currentTime()==null||r.duration()==null)throw new IllegalArgumentException("Playback currentTime and duration must be supplied together");i.setPlaybackPosition(r.currentTime(),r.duration());}else{i.setProgressPercent(r.progressPercent());}return dto(library.save(i));}
 @PatchMapping("/{titleId}/rating")public LibraryDto rate(@PathVariable java.util.UUID titleId,@Valid @RequestBody RatingRequest r){LibraryItem i=library.findByAccountIdAndTitleId(current.require().getId(),titleId).orElseThrow(()->new IllegalArgumentException("Add this title to your library first"));i.setUserRating(r.rating());return dto(library.save(i));}
}